-- سجلات الجرد: للإضافة فقط (عدّ أو إلغاء عدّ). التصحيح بسجل جديد ولا يُعدَّل أي سجل.
-- Audit records: append-only (a count or a void). Corrections are new records; nothing is ever edited.
--
-- `id` يولّده الجهاز وهو مفتاح عدم التكرار لكل حدث، فإعادة إرسال طابور دون اتصال لا تُكرّر العدّ.
-- `id` is generated by the device and is the per-event idempotency key, so replaying an offline queue never double-counts.
CREATE TABLE audit_records (
  id            uuid PRIMARY KEY,
  company_id    uuid NOT NULL REFERENCES companies (id),
  task_id       uuid NOT NULL REFERENCES audit_tasks (id),
  user_id       uuid NOT NULL REFERENCES users (id),
  kind          text NOT NULL CHECK (kind IN ('count', 'void')),
  location_id   uuid REFERENCES locations (id),
  -- null = باركود مجهول (يُراجَع لاحقاً). null = unknown barcode (reviewed later).
  item_id       uuid REFERENCES items (id),
  barcode       text CHECK (barcode IS NULL OR barcode ~ '^[^\s[:cntrl:]]{1,64}$'),
  quantity      numeric(20, 6),
  unit_id       uuid REFERENCES item_units (id),
  -- بالوحدة الأساسية، يحسبها الخادم من معامل الوحدة. In the base unit, computed by the server from the unit factor.
  base_quantity numeric(20, 6),
  voids_id      uuid REFERENCES audit_records (id),
  note          text CHECK (note IS NULL OR length(note) <= 200),
  scanned_at    timestamptz NOT NULL,
  received_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT audit_records_shape CHECK (
    (kind = 'count' AND barcode IS NOT NULL AND quantity > 0 AND base_quantity > 0 AND voids_id IS NULL)
    OR (kind = 'void' AND voids_id IS NOT NULL AND quantity IS NULL AND base_quantity IS NULL)
  )
);
-- السجل الواحد يُلغى مرة واحدة فقط. A record can be voided only once.
CREATE UNIQUE INDEX audit_records_voids_uq ON audit_records (voids_id) WHERE voids_id IS NOT NULL;
CREATE INDEX audit_records_task_idx ON audit_records (task_id, received_at, id);
CREATE INDEX audit_records_task_item_idx ON audit_records (task_id, item_id);

ALTER TABLE audit_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_records FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON audit_records
  FOR ALL TO inventory_app
  USING (company_id = app_company_id())
  WITH CHECK (company_id = app_company_id());
-- لا UPDATE ولا DELETE: صلاحية + مشغّل يمنعهما حتى على المالك.
-- No UPDATE/DELETE: no grant, plus a trigger that blocks them even for the table owner.
GRANT SELECT, INSERT ON audit_records TO inventory_app;

CREATE FUNCTION audit_records_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'audit_records is append-only' USING ERRCODE = 'integrity_constraint_violation';
END;
$$;
CREATE TRIGGER audit_records_no_change
  BEFORE UPDATE OR DELETE ON audit_records
  FOR EACH ROW EXECUTE FUNCTION audit_records_immutable();
CREATE TRIGGER audit_records_no_truncate
  BEFORE TRUNCATE ON audit_records
  FOR EACH STATEMENT EXECUTE FUNCTION audit_records_immutable();
